"""Fixtures for the JavaScript text utilities of the decoder questions, generated by the Python originals (marimba-audio 0.1.2).

Third-party code: run in the isolated sandbox. Writes decoder-text.json:
  normalize        [input, normalize(input)] pairs (transcripts, spellings with accents, ß, ς, ſ, Devanagari, CJK, digits, underscores, ...)
  codepoints       {codepoint: normalize(chr(cp))} for every code point whose result is not the lower-cased character itself (all of Unicode)
  repetitions      [input, detect_and_fix_repetitions(input)] (character runs, repeated patterns, edge lengths)
  parse            [raw, parse_asr_output(raw)[1]]
  decode           [ids, text] decoded by the Qwen3-ASR tokenizer (skip_special_tokens=True, clean_up_tokenization_spaces=False)
  fractions        [term, hypotheses, exact_fraction]

  python decoder_text_fixtures.py --qwen <checkpoint dir> --refs <dec_ref.jsonl> --out decoder-text.json
"""
import argparse, json, random, unicodedata

ap = argparse.ArgumentParser()
ap.add_argument("--qwen", required=True)
ap.add_argument("--refs", required=True)
ap.add_argument("--out", required=True)
a = ap.parse_args()

from marimba.lexical import normalize, exact_fraction
from marimba._vendor.qwen_asr.utils import detect_and_fix_repetitions, parse_asr_output
from transformers import AutoTokenizer

rows = [json.loads(l) for l in open(a.refs)]
words = []
for r in rows:
    words += [r["tr"], *r["hyps"], r.get("fn", "")]
extra = ["Ação não é São João", "ÀÉÎÕÜ çÇ ñ", "Straße STRASSE Maß", "ΟΔΥΣΣΕΥΣ Οδυσσεύς ς σ", "ſtrasse ǰ ŉ", "İstanbul ıi", "हिन्दी भाषा", "日本語のテキスト１２３", "é é ẹ́",
         "a_b c__d _e_", "x y z　w", "ﬁne ﬃ ℌ ①②③ ² ½", "hello, world! 'quote' \"dq\" — dash", "كلمة عربية", "ไทย", "ǅ ǆ Ǆ", "ᏣᎳᎩ ꭰꭱ", "​zero‍width", "1,000.50 R$ 3", ""]
norm = [[t, normalize(t)] for t in words + extra]
cps = {}
for cp in range(0x30000):
    if 0xD800 <= cp < 0xE000:
        continue
    c = chr(cp)
    n = normalize(c)
    if n != c.lower():
        cps[format(cp, "x")] = n
rep = []
for s in ["aaaaaaaaaaaaaaaaaaaaaaaaaaa bbb", "a" * 20, "a" * 21, "ab" * 25, "abc" * 19, "abc" * 20, "abc" * 21 + "xyz", "xy" + "la " * 30 + "end", "ha" * 40, "x" * 5, "", "hello world " * 22, "ç" * 30, "😀" * 25, "😀😁" * 21,
          "no repetition here at all", "a" * 19 + "b" * 19 + "c" * 25, ("0123456789" * 3), "ab" * 20, "ab" * 19 + "c"]:
    rep.append([s, detect_and_fix_repetitions(s)])
for r in rows[:20]:
    for h in r["hyps"]:
        rep.append([h, detect_and_fix_repetitions(h)])
parse = []
for raw in ["language Portuguese<asr_text>Olá, mundo.", "  language Portuguese<asr_text>  espaço  ", "language None<asr_text>", "language None<asr_text>algo", "sem etiqueta", "", "   ",
            "language English\n<asr_text>two\nlines", "language Portuguese<asr_text>" + "ha" * 50, "<asr_text>só texto", "language Chinese<asr_text>你好，世界", "lang x<asr_text> y ", "a<asr_text>b<asr_text>c"]:
    parse.append([raw, parse_asr_output(raw)[1]])
for r in rows[:30]:
    parse.append(["language Portuguese<asr_text>" + r["hyps"][0], parse_asr_output("language Portuguese<asr_text>" + r["hyps"][0])[1]])
tok = AutoTokenizer.from_pretrained(a.qwen)
rng = random.Random(7)
dec = []
specials = [151643, 151644, 151645, 151669, 151670, 151676, 151704]
for r in rows:
    ids = tok.encode("language Portuguese<asr_text>" + r["hyps"][0] + "<|im_end|>", add_special_tokens=False)
    dec.append([ids, tok.decode(ids, skip_special_tokens=True, clean_up_tokenization_spaces=False)])
for _ in range(300):
    ids = [rng.randrange(0, 151643) for _ in range(rng.randrange(1, 12))] + [rng.choice(specials)] + [rng.randrange(0, 151643) for _ in range(rng.randrange(0, 6))]
    dec.append([ids, tok.decode(ids, skip_special_tokens=True, clean_up_tokenization_spaces=False)])
for t in ["日本語", "😀😁", "é́", "Ação"]:
    ids = tok.encode(t, add_special_tokens=False)
    dec.append([ids, tok.decode(ids, skip_special_tokens=True, clean_up_tokenization_spaces=False)])
    dec.append([ids[:-1], tok.decode(ids[:-1], skip_special_tokens=True, clean_up_tokenization_spaces=False)])  # a cut multi-byte sequence
fr = []
for r in rows[:25]:
    for t in list(r["terms"])[:6] + ["", "marimba"]:
        try:
            fr.append([t, r["hyps"], exact_fraction(t, r["hyps"])])
        except ValueError:
            fr.append([t, r["hyps"], None])
json.dump({"normalize": norm, "codepoints": cps, "repetitions": rep, "parse": parse, "decode": dec, "fractions": fr, "unicode": unicodedata.unidata_version}, open(a.out, "w", encoding="utf-8"), ensure_ascii=False, separators=(",", ":"))
print({k: len(v) for k, v in json.load(open(a.out, encoding="utf-8")).items() if hasattr(v, "__len__")})
